120	/**
121	 * Creates one runtime query function and its subscription API.
122	 *
123	 * Queries share the same validation contract as commands, but may also run preload logic and emit
124	 * reactive updates when subscribed to.
125	 */
126	function createQuery<TState>(
127	  serviceId: string,
128	  name: string,
129	  queryDef: RuntimeQueryDefinition<TState>,
130	  selfRef: WritableSelf<TState>,
131	  loadStaticState?: StaticStateLoader
132	): Query<unknown, unknown> {
133	  const createQueryCtx = (): QueryCtx<TState> => ({ self: selfRef });
134	
135	  /** Runs the query handler and validates the resolved output value. */
136	  const runHandler = async (input: unknown): Promise<unknown> => {
137	    const output = await queryDef.handler(input, createQueryCtx());
138	
139	    return validateSchema(queryDef.output, output, {
140	      kind: 'query',
141	      serviceId,
142	      name,
143	      phase: 'output',
144	    });
145	  };
146	
147	  /** Runs either static-store preloading or the query's own preload hook before execution. */
148	  const prepareQuery = async (input: unknown): Promise<void> => {
149	    if (loadStaticState !== undefined) {
150	      await loadStaticState(input);
151	      return;
152	    }
153	
154	    await queryDef.preload?.(input, createQueryCtx());
155	  };
156	
157	  /**
158	   * Subscribes to a query by wiring an alien-signals computed around the handler.
159	   *
160	   * The initial emission and every subsequent emission are validated the same way direct query
161	   * calls are validated.
162	   */
163	  const subscribe = (input: unknown, callback: (value: unknown) => void): (() => void) => {
164	    let unsubscribe = () => {};
165	    let active = true;
166	
167	    /** Connects the reactive computation after the caller input has been validated. */
168	    const connect = async (validatedInput: unknown) => {
169	      if (!active) {
170	        return;
171	      }
172	
173	      // Kick off preload in parallel so subscriptions can observe the state transition it causes.
174	      void prepareQuery(validatedInput).catch(rethrowAsync);
175	
176	      // `computed()` tracks which signals the handler reads so the effect can re-run on changes.
177	      const comp = computed(() => queryDef.handler(validatedInput, createQueryCtx()));
178	      unsubscribe = effect(() => {
179	        // Normalize sync and async handlers before validating and publishing the next value.
180	        void Promise.resolve(comp()).then(async (output) => {
181	          const validatedOutput = await validateSchema(queryDef.output, output, {
182	            kind: 'query',
183	            serviceId,
184	            name,
185	            phase: 'output',
186	          });
187	
188	          if (active) {
189	            // Guard against late async completions after the subscriber has already unsubscribed.
190	            callback(validatedOutput);
191	          }
192	        }, rethrowAsync);
193	      });
194	    };
195	
196	    // Validate once up front so the reactive graph only ever sees parsed query input.
197	    void validateSchema(queryDef.input, input, {
198	      kind: 'query',
199	      serviceId,
200	      name,
201	      phase: 'input',
202	    }).then(connect, rethrowAsync);
203	
204	    return () => {
205	      active = false;
206	      unsubscribe();
207	    };
208	  };
209	
210	  const query = (async (input: unknown) => {
211	    const validatedInput = await validateSchema(queryDef.input, input, {
212	      kind: 'query',
213	      serviceId,
214	      name,
215	      phase: 'input',
216	    });
217	
218	    await prepareQuery(validatedInput);
219	
220	    return runHandler(validatedInput);
221	  }) as Query<unknown, unknown>;
222	
223	  query.subscribe = subscribe;
224	  return query;
225	}
